import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static long cost(List<Integer> B) {int n = B.size();if (n < 2) return 0;long dpLow = 0;long dpHigh = 0;for (int i = 1; i < n; i++) {int prevB = B.get(i - 1);int currB = B.get(i);long nextLow = Math.max(dpLow + Math.abs(1 - 1), dpHigh + Math.abs(1 - prevB));long nextHigh = Math.max(dpLow + Math.abs(currB - 1), dpHigh + Math.abs(currB - prevB));dpLow = nextLow;dpHigh = nextHigh;}return Math.max(dpLow, dpHigh);}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));int t = Integer.parseInt(bufferedReader.readLine().trim());IntStream.range(0, t).forEach(tItr -> {try {int n = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> B = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());long result = Result.cost(B);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();} catch (IOException ex) {throw new RuntimeException(ex);}});bufferedReader.close();bufferedWriter.close();}}